import re, tempfile, pathlib
root = pathlib.Path(tempfile.mkdtemp())
for d in ("etc/init.d", "usr/bin"):
    (root / d).mkdir(parents=True)
(root / "etc/shadow").write_text("root::0:0:99999:7:::\nuser:$6$abc$xyz:0:0:::\n")
(root / "etc/init.d/S50telnet").write_text("telnetd -l /bin/sh &\n")
(root / "usr/bin/updater").write_bytes(b"\x7fELF..-----BEGIN RSA PRIVATE KEY-----\nMIIE..")
(root / "usr/bin/diag").write_bytes(b"\x7fELF..\x00strcpy\x00gets\x00")

RULES = [
    ("긴급", "개인키가 펌웨어 안에 있음", re.compile(rb"-----BEGIN (RSA |EC )?PRIVATE KEY-----")),
    ("높음", "telnet 디버그 셸이 켜짐", re.compile(rb"telnetd")),
    ("보통", "위험 함수(strcpy/gets) 가져다 씀", re.compile(rb"\x00(strcpy|gets)\x00")),
]
found = []
for p in sorted(root.rglob("*")):
    if not p.is_file():
        continue
    data, rel = p.read_bytes(), p.relative_to(root).as_posix()
    for level, name, rx in RULES:
        if rx.search(data):
            found.append((level, rel, name))
    if p.name == "shadow":
        for line in data.splitlines():
            f = line.split(b":")
            if len(f) > 1 and f[1] == b"":
                found.append(("긴급", rel, f"비밀번호 없는 계정 {f[0].decode()}"))

order = {"긴급": 0, "높음": 1, "보통": 2}
for level, rel, name in sorted(found, key=lambda x: order[x[0]]):
    print(f"[{level}] {rel}: {name}")
print(f"총 {len(found)}건, 긴급 {sum(x[0]=='긴급' for x in found)}건 → 긴급만 바로 보고")

# [긴급] etc/shadow: 비밀번호 없는 계정 root
# [긴급] usr/bin/updater: 개인키가 펌웨어 안에 있음
# [높음] etc/init.d/S50telnet: telnet 디버그 셸이 켜짐
# [보통] usr/bin/diag: 위험 함수(strcpy/gets) 가져다 씀
# 총 4건, 긴급 2건 → 긴급만 바로 보고
